#!/usr/bin/env node
// C8 (0.8.11) — assemble `src/types/generated.ts` from the per-type ts-rs
// bindings in `backend/bindings/`. `make typegen` runs `cargo test
// export_bindings` (ts-rs writes one file per type) then this script, which:
//   • strips each file's `// generated by ts-rs` header + `import type …` lines
//     (in one aggregate file, cross-type refs resolve by name, no imports),
//   • keeps ts-rs's native `export type X = …` verbatim (object types, string
//     unions, AND tagged unions `{…} | {…}` — converting the latter to an
//     interface would be malformed; `export type` + `import type` work for all),
//   • concatenates in a STABLE order (type name, code-point — never locale
//     order) so the output is deterministic; `--check` (CI, `make
//     typegen-check`) fails when the committed file differs from a fresh run,
//   • refuses a bindings dir that declares one type two different ways (stale
//     export) instead of keeping whichever file sorted first.
//
// Historically `generated.ts` was hand-maintained and drifted from the Rust
// models (86 missing types at the 2026-07 audit). This closes that gap.
import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join, basename, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const BINDINGS = join(HERE, '..', '..', 'backend', 'bindings');
const RUST_SRC = join(HERE, '..', '..', 'backend', 'src');
const OUT = join(HERE, '..', 'src', 'types', 'generated.ts');

// ─── serde-default → optional (C1) ─────────────────────────────────────────
// ts-rs only emits `?` for `skip_serializing_if` / `#[ts(optional)]`; a bare
// `#[serde(default)]` — the contract that lets API clients omit the field —
// stays REQUIRED in the binding. That information only exists in the Rust
// source, so scan it: struct → set of fields to optionalize in the aggregate.
// Container-level `#[serde(default)]` marks every field. Handles per-field
// `serde(rename)`, container `rename_all = "camelCase"`, `#[ts(rename)]`.

const toCamel = s => s.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());

export function scanRustOptionals(dir) {
  /** @type {Map<string, Set<string>>} TS type name → field names to mark `?` */
  const optionals = new Map();
  const stack = [dir];
  while (stack.length) {
    const d = stack.pop();
    for (const name of readdirSync(d)) {
      const p = join(d, name);
      if (statSync(p).isDirectory()) { stack.push(p); continue; }
      if (!name.endsWith('.rs')) continue;
      const src = readFileSync(p, 'utf8');
      // One match per struct: the attribute block directly above + the body.
      for (const m of src.matchAll(
        /((?:^[ \t]*#\[[^\n]*\]\s*\n|^[ \t]*\/\/\/[^\n]*\n)+)^[ \t]*pub struct (\w+)\s*\{([\s\S]*?)^\}/gm
      )) {
        const [, attrs, rustName, body] = m;
        if (!/derive\([^)]*\bTS\b/.test(attrs) && !/#\[ts\(/.test(attrs)) continue;
        // Only REQUEST-direction types: there `serde(default)` (or a plain
        // `Option<T>`, which serde reads as None when missing) means "the
        // client may omit this". On a response/bidirectional type the field
        // is always present in the payload — optionalizing it would force
        // spurious null-checks at every read site. Direction = Deserialize
        // without Serialize, or an explicit `…Request` name (some request
        // types derive Serialize incidentally).
        const tsName = attrs.match(/#\[ts\([^\]]*rename\s*=\s*"(\w+)"/)?.[1] ?? rustName;
        const derives = attrs.match(/derive\(([^)]*)\)/)?.[1] ?? '';
        const isRequest = (/\bDeserialize\b/.test(derives) && !/\bSerialize\b/.test(derives))
          || /Request$/.test(tsName);
        if (!isRequest) continue;
        const containerDefault = /#\[serde\((?:[^\]]*,\s*)?default\s*[,)\]]/.test(attrs);
        const renameAll = attrs.match(/rename_all\s*=\s*"(\w+)"/)?.[1];
        const set = optionals.get(tsName) ?? new Set();
        // Walk fields with the attribute lines attached to each.
        for (const f of body.matchAll(
          /((?:^[ \t]*#\[[^\n]*\]\s*\n)*)^[ \t]*pub (?:r#)?(\w+)\s*:\s*([^,\n]+)/gm
        )) {
          const [, fAttrs, fName, fType] = f;
          if (/#\[serde\([^\]]*skip[,)\s]/.test(fAttrs)) continue; // not exported
          const fieldDefault = /#\[serde\([^\]]*\bdefault\b/.test(fAttrs);
          // serde deserializes a MISSING `Option<T>` as None even without
          // `default` — on a request type every Option field is omittable.
          const isOption = /^Option\s*</.test(fType.trim());
          if (!containerDefault && !fieldDefault && !isOption) continue;
          let tsField = fAttrs.match(/#\[serde\([^\]]*rename\s*=\s*"([^"]+)"/)?.[1] ?? fName;
          if (!fAttrs.includes('rename =') && renameAll === 'camelCase') tsField = toCamel(fName);
          set.add(tsField);
        }
        if (set.size) optionals.set(tsName, set);
      }
    }
  }
  return optionals;
}

/** Mark the scanned serde-default fields optional inside one type block. */
export function applyOptionals(name, block, optionals) {
  const fields = optionals.get(name);
  if (!fields) return block;
  for (const f of fields) {
    // `field:` preceded by `{`, `,` or start-of-line — never touches an
    // already-optional `field?:` nor occurrences inside string literals.
    block = block.replace(new RegExp(`([{,]\\s*|^\\s*)${f}:`, 'gm'), `$1${f}?:`);
  }
  return block;
}

// ─── assembly (runs only when invoked directly, so tests can import) ───────
import { argv } from 'node:process';
import { resolve } from 'node:path';
const invokedDirectly = argv[1] && resolve(argv[1]) === fileURLToPath(import.meta.url);

/** Every `.ts` binding under `dir`, recursively. */
function walk(dir) {
  const out = [];
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) out.push(...walk(p));
    else if (name.endsWith('.ts')) out.push(p);
  }
  return out;
}

/** Code-point order: independent of the runtime's locale / ICU data. */
const byCodePoint = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

export const HEADER = `// ╔═══════════════════════════════════════════════════════════════════════════╗
// ║  AUTO-GENERATED — do not edit manually.                                     ║
// ║  Source: ts-rs bindings in backend/bindings/ (\`#[derive(TS)]\` on Rust      ║
// ║  models). Assembled by frontend/scripts/assemble-generated-types.mjs.       ║
// ║  Regenerate: \`make typegen\`. CI fails if this file drifts from the models.  ║
// ╚═══════════════════════════════════════════════════════════════════════════╝
`;

/**
 * Assemble the aggregate from a bindings directory + the Rust source (for the
 * serde-default optionals). Pure: same inputs → same bytes. Blocks are ordered
 * by type name in code-point order, never by file-system or locale order.
 *
 * A type declared by two binding files with DIFFERENT content means the
 * directory holds a stale export (a renamed/moved type, an old run): that
 * throws instead of silently keeping whichever file sorted first.
 */
export function assembleGenerated(bindingsDir, rustSrcDir) {
  const optionals = scanRustOptionals(rustSrcDir);
  /** @type {Map<string, {block: string, file: string}>} */
  const byName = new Map();
  for (const f of walk(bindingsDir)) {
    let src = readFileSync(f, 'utf8');
    src = src
      .replace(/^\/\/ This file was generated by \[ts-rs\].*$/m, '')
      .replace(/^import type .*;\s*$/gm, '')
      .trim();
    if (!src) continue;
    const m = src.match(/export type (\w+) =/);
    const name = m ? m[1] : basename(f, '.ts');
    // Normalize ts-rs's `bigint` (Rust u64/i64/usize) → `number`. Kronn's such
    // values (token counts, durations-ms, byte sizes, sequence numbers) are all
    // well under 2^53, the whole frontend does `number` arithmetic on them, and
    // JSON.parse yields `number` anyway (not BigInt). Matches the convention the
    // hand-maintained file used before this generator existed.
    src = src.replace(/\bbigint\b/g, 'number');
    // ts-rs leaves trailing spaces after fields that precede doc comments —
    // thousands of `git diff --check` violations. Normalize per line.
    src = src.split('\n').map(l => l.replace(/[ \t]+$/, '')).join('\n');
    src = applyOptionals(name, src, optionals);
    const prev = byName.get(name);
    if (prev) {
      // A binding exported under two paths (same content) is harmless.
      if (prev.block !== src) {
        throw new Error(
          `type ${name} is declared differently by ${prev.file} and ${f} — `
          + 'the bindings directory is stale; delete it and re-run the ts-rs export.',
        );
      }
      continue;
    }
    byName.set(name, { block: src, file: f });
  }
  const names = [...byName.keys()].sort(byCodePoint);
  const blocks = names.map(n => byName.get(n).block);
  return { content: HEADER + '\n' + blocks.join('\n\n') + '\n', count: blocks.length };
}

// CLI: node assemble-generated-types.mjs [--bindings DIR] [--out FILE] [--check]
// `--check` writes nothing and exits 1 when OUT differs from a fresh assembly.
if (invokedDirectly) {
  const args = argv.slice(2);
  const opt = flag => {
    const i = args.indexOf(flag);
    return i >= 0 ? resolve(args[i + 1]) : null;
  };
  const { content, count } = assembleGenerated(opt('--bindings') ?? BINDINGS, RUST_SRC);
  const out = opt('--out') ?? OUT;
  if (args.includes('--check')) {
    if (readFileSync(out, 'utf8') !== content) {
      console.error(`${out} differs from a fresh regeneration (${count} types) — run \`make typegen\` and commit it.`);
      process.exit(1);
    }
    console.log(`${out} matches a fresh regeneration (${count} types).`);
  } else {
    writeFileSync(out, content);
    console.log(`assembled ${count} types → ${out}`);
  }
}
